use aa_mapworld::{MapArchive,Inventory,actor_payload::ActorTail,saved_components::SavedComponent};
use serde_json::json;use std::{collections::BTreeMap,path::{Path,PathBuf}};
fn paths(p:&Path,v:&mut Vec<PathBuf>){for e in std::fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){paths(&p,v)}else if p.extension().is_some_and(|e|e.eq_ignore_ascii_case("rmp")){v.push(p)}}}
fn main(){let root=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../reconstruction/assets/original/Data/Maps");let mut maps=Vec::new();paths(&root,&mut maps);maps.sort();let mut failures=BTreeMap::new();let mut examples=BTreeMap::new();let mut slots=BTreeMap::new();let mut complete=0;for p in maps{let map=MapArchive::from_bytes(std::fs::read(&p).unwrap()).unwrap();let inv=Inventory::decode(&map,128<<20).unwrap();for r in inv.placements{let Some(actor)=r.actor else{continue};let result=ActorTail::decode_prefix_with_components(&r.opaque_tail,actor.version,0,|slot,_,bytes|{let(value,n)=SavedComponent::decode_prefix(slot,bytes)?;*slots.entry(slot).or_insert(0usize)+=1;Ok((n,if let SavedComponent::Properties(v)=value{Some(v)}else{None}))});match result{Ok((_,n))if n==r.opaque_tail.len()=>complete+=1,other=>{let reason=match other{Ok((_,n))=>format!("trailing bytes: {}",r.opaque_tail.len()-n),Err(e)=>e.to_string()};*failures.entry(reason.clone()).or_insert(0usize)+=1;examples.entry(reason).or_insert(json!({"map":p,"ordinal":r.record_ordinal,"id":String::from_utf16_lossy(&r.thing_id_utf16),"tail_offset":r.opaque_tail_span.offset,"tail_length":r.opaque_tail.len()}));}}}}
println!("{}",serde_json::to_string_pretty(&json!({"complete_actor_tails":complete,"decoded_components":slots,"failures":failures,"examples":examples})).unwrap());}
